import type { Claim, Rates } from "./model.ts";
import type { Row } from "./store.ts";

export type Notice = { id: string; person: string; euroCents: number };

export type Deps = {
  limitFor: (person: string) => number;
  inEuroCents: (row: Row, rates: Rates) => number;
  send: (notice: Notice) => void;
};

export type Decision = { id: string; outcome: "approved" | "needs second approver"; euroCents: number };

export function approve(row: Row, rates: Rates, deps: Deps): Decision {
  const claim = row as unknown as Claim;
  if (claim.amount <= 0) throw new Error(`${claim.id}: nothing to approve`);
  const euroCents = deps.inEuroCents(row, rates);
  const outcome = euroCents > deps.limitFor(claim.person) ? "needs second approver" : "approved";
  if (outcome === "approved") deps.send({ id: claim.id, person: claim.person, euroCents });
  return { id: claim.id, outcome, euroCents };
}

