import { parseArgs } from "node:util";
import { approve } from "./approve.ts";
import { limitFor } from "./limits.ts";
import { postToAccounting } from "./notify.ts";
import { detail, euros, listing, totalsTable } from "./report.ts";
import { InvalidClaim } from "./schema.ts";
import { findClaim, loadClaims, loadRates, UnknownClaim } from "./store.ts";
import { inEuroCents, MissingRate, totalBy } from "./totals.ts";

const USAGE = "usage: claimbox <list | total | show <id> | approve <id>> [--by category|person] [--claims file] [--rates file] [--notify url]";

function main(argv: string[]): void {
  const { values, positionals } = parseArgs({
    args: argv,
    allowPositionals: true,
    options: {
      by: { type: "string", default: "category" },
      claims: { type: "string", default: "data/claims.json" },
      rates: { type: "string", default: "data/rates.json" },
      notify: { type: "string" },
    },
  });
  const [command, id] = positionals;
  const rows = loadClaims(values.claims);
  const rates = loadRates(values.rates);

  if (command === "list") {
    listing(rows).forEach((line) => console.log(line));
  } else if (command === "total") {
    if (values.by !== "category" && values.by !== "person") {
      console.log(USAGE);
      process.exitCode = 2;
      return;
    }
    totalsTable(totalBy(rows, values.by, rates)).forEach((line) => console.log(line));
  } else if (command === "show" && id !== undefined) {
    const row = findClaim(rows, id);
    detail(row, inEuroCents(row, rates)).forEach((line) => console.log(line));
  } else if (command === "approve" && id !== undefined) {
    const send = values.notify ? postToAccounting(values.notify) : () => {};
    const decision = approve(findClaim(rows, id), rates, { limitFor, inEuroCents, send });
    console.log(`${decision.id}: ${decision.outcome} (${euros(decision.euroCents)} EUR)`);
  } else {
    console.log(USAGE);
    process.exitCode = 2;
  }
}

try {
  main(process.argv.slice(2));
} catch (error) {
  if (error instanceof InvalidClaim || error instanceof UnknownClaim || error instanceof MissingRate) {
    console.log(`error: ${error.message}`);
    process.exitCode = 1;
  } else {
    throw error;
  }
}

