import type { Notice } from "./approve.ts";

export function postToAccounting(url: string): (notice: Notice) => void {
  return (notice) => {
    void fetch(url, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ claim: notice.id, person: notice.person, amount_eur_cents: notice.euroCents }),
    }).catch(() => {
      console.log(`warning: accounting was not told about ${notice.id}`);
    });
  };
}

