import type { Row } from "./store.ts";

export function euros(cents: number): string {
  return (cents / 100).toFixed(2);
}

export function claimLine(row: Row): string {
  const claim = row as any;
  const person = String(claim.person ?? "unknown");
  const amount = `${euros(claim.amount)} ${claim.currency}`;
  const flag = claim.receipt ? "" : "  (no receipt)";
  const note = claim.note ?? "";
  return `${claim.id}  ${claim.date}  ${person.padEnd(6)}  ${claim.category.padEnd(9)}  ${amount.padStart(11)}${flag}${note ? "  " + note : ""}`;
}

export function listing(rows: Row[]): string[] {
  return rows.map(claimLine);
}

export function totalsTable(pairs: [string, number][]): string[] {
  const lines = pairs.map(([name, cents]) => `${name.padEnd(9)}  ${euros(cents).padStart(9)} EUR`);
  const sum = pairs.reduce((acc, [, cents]) => acc + cents, 0);
  lines.push(`${"total".padEnd(9)}  ${euros(sum).padStart(9)} EUR`);
  return lines;
}

export function detail(row: Row, euroCents: number): string[] {
  const claim = row as any;
  return [
    `claim     ${claim.id}`,
    `person    ${String(claim.person ?? "unknown")}`,
    `category  ${claim.category}`,
    `date      ${claim.date}`,
    `amount    ${euros(claim.amount)} ${claim.currency} (${euros(euroCents)} EUR)`,
    `receipt   ${claim.receipt ?? "missing"}`,
    `note      ${claim.note ?? "-"}`,
  ];
}

