import { CATEGORIES, CURRENCIES } from "./model.ts";
import type { Claim } from "./model.ts";

export class InvalidClaim extends Error {}

function text(o: Record<string, unknown>, key: string): string {
  const v = o[key];
  if (typeof v !== "string" || v.trim() === "") throw new InvalidClaim(`${key} must be a non-empty string`);
  return v;
}

function optionalText(o: Record<string, unknown>, key: string): string | undefined {
  const v = o[key];
  if (v === undefined) return undefined;
  if (typeof v !== "string") throw new InvalidClaim(`${key} must be a string when present`);
  return v;
}

function oneOf<T extends string>(o: Record<string, unknown>, key: string, allowed: readonly T[]): T {
  const v = text(o, key);
  if (!allowed.includes(v as T)) throw new InvalidClaim(`${key} must be one of ${allowed.join(", ")}`);
  return v as T;
}

function cents(o: Record<string, unknown>, key: string): number {
  const v = o[key];
  if (typeof v !== "number" || !Number.isInteger(v) || v <= 0) {
    throw new InvalidClaim(`${key} must be a positive whole number of cents`);
  }
  return v;
}

function day(o: Record<string, unknown>, key: string): string {
  const v = text(o, key);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(v)) throw new InvalidClaim(`${key} must look like 2026-03-31`);
  return v;
}

export function parseClaim(input: unknown): Claim {
  if (typeof input !== "object" || input === null || Array.isArray(input)) {
    throw new InvalidClaim("a claim must be an object");
  }
  const o = input as Record<string, unknown>;
  const claim: Claim = {
    id: text(o, "id"),
    person: text(o, "person"),
    category: oneOf(o, "category", CATEGORIES),
    currency: oneOf(o, "currency", CURRENCIES),
    amount: cents(o, "amount"),
    date: day(o, "date"),
  };
  const note = optionalText(o, "note");
  if (note !== undefined) claim.note = note;
  const receipt = optionalText(o, "receipt");
  if (receipt !== undefined) claim.receipt = receipt;
  return claim;
}

