import { readFileSync } from "node:fs";
import type { Rates } from "./model.ts";
import { InvalidClaim, parseClaim } from "./schema.ts";

export type Row = Record<string, unknown>;

export class UnknownClaim extends Error {
  constructor(id: string) {
    super(`no claim ${id}`);
  }
}

export function loadClaims(path: string): Row[] {
  const raw: unknown = JSON.parse(readFileSync(path, "utf8"));
  if (!Array.isArray(raw)) throw new InvalidClaim("the claims file must hold a list");
  const rows: Row[] = [];
  for (const item of raw) {
    const claim = parseClaim(item);
    const row: Row = claim;
    rows.push(row);
  }
  return rows;
}

export function findClaim(rows: Row[], id: string): Row {
  const row = rows.find((r) => r.id === id);
  if (row === undefined) throw new UnknownClaim(id);
  return row;
}

export function loadRates(path: string): Rates {
  return JSON.parse(readFileSync(path, "utf8")) as Rates;
}

