import { CATEGORIES } from "./model.ts";
import type { Claim, Rates } from "./model.ts";
import type { Row } from "./store.ts";

export class MissingRate extends Error {
  constructor(currency: string) {
    super(`no rate for ${currency}`);
  }
}

export function inEuroCents(row: Row, rates: Rates): number {
  const claim = row as unknown as Claim;
  if (typeof claim.amount !== "number" || Number.isNaN(claim.amount)) return 0;
  const rate = rates[claim.currency];
  if (rate === undefined) throw new MissingRate(claim.currency);
  return Math.round(claim.amount * rate);
}

export function totalBy(rows: Row[], key: "category" | "person", rates: Rates): [string, number][] {
  const sums = new Map<string, number>();
  for (const row of rows) {
    const claim = row as unknown as Claim;
    let group: string = key === "category" ? claim.category : claim.person;
    if (key === "category" && !CATEGORIES.includes(claim.category)) group = "other";
    if (key === "person" && !claim.person) group = "unknown";
    sums.set(group, (sums.get(group) ?? 0) + inEuroCents(row, rates));
  }
  return [...sums.entries()].sort(([a], [b]) => a.localeCompare(b));
}

