import assert from "node:assert/strict";
import test from "node:test";
import { approve } from "../src/approve.ts";
import type { Notice } from "../src/approve.ts";

const row = { id: "c-1", person: "ana", category: "meals", currency: "EUR", amount: 1000, date: "2026-03-02" };

test("a claim under the limit is approved and accounting is told", () => {
  const sent: Notice[] = [];
  const decision = approve(row, {}, {
    limitFor: () => 1000,
    inEuroCents: () => 500,
    send: (notice) => sent.push(notice),
  });
  assert.equal(decision.outcome, "approved");
  assert.deepEqual(sent, [{ id: "c-1", person: "ana", euroCents: 500 }]);
});

test("a claim over the limit needs a second approver and nothing is sent", () => {
  const sent: Notice[] = [];
  const decision = approve(row, {}, {
    limitFor: () => 1000,
    inEuroCents: () => 5000,
    send: (notice) => sent.push(notice),
  });
  assert.equal(decision.outcome, "needs second approver");
  assert.deepEqual(sent, []);
});

