import assert from "node:assert/strict";
import test from "node:test";
import { InvalidClaim, parseClaim } from "../src/schema.ts";

const good = { id: "c-1", person: "ana", category: "meals", currency: "EUR", amount: 1250, date: "2026-03-02" };

test("a complete claim comes back with its fields", () => {
  assert.deepEqual(parseClaim({ ...good, note: "team lunch" }), { ...good, note: "team lunch" });
});

test("a claim without a person is refused", () => {
  assert.throws(() => parseClaim({ ...good, person: "" }), InvalidClaim);
  assert.throws(() => parseClaim({ ...good, person: undefined }), InvalidClaim);
});

test("an amount must be a positive whole number of cents", () => {
  for (const amount of [0, -5, 12.5, "1250", undefined, Number.NaN]) {
    assert.throws(() => parseClaim({ ...good, amount }), InvalidClaim);
  }
});

test("an unknown category or currency is refused", () => {
  assert.throws(() => parseClaim({ ...good, category: "gifts" }), /category must be one of/);
  assert.throws(() => parseClaim({ ...good, currency: "JPY" }), /currency must be one of/);
});

test("anything that is not an object is refused", () => {
  for (const input of [null, "c-1", 7, [good]]) {
    assert.throws(() => parseClaim(input), InvalidClaim);
  }
});

